def f(n):
    """ n parametresini alan ve n boyutunda bir liste döndüren f fonksiyonunu uygula.
    Liste içinde i indeksindeki elemanın değeri, i çift sayı ise i'nin faktöriyeli,
    aksi takdirde 1'den i'ye kadar olan sayıların toplamı olmalıdır.
    i değeri 1'den başlar.
    i'nin faktöriyeli, 1'den i'ye kadar olan sayıların çarpımıdır (1 * 2 * ... * i).
    Örnek:
    f(5) == [1, 2, 6, 24, 15]
    """
    result = []
    for i in range(1, n + 1):
        if i % 2 == 0:
            result.append(i * factorial(i))
        else:
            result.append(sum(range(1, i + 1)))
    return result

def factorial(n):
    """ n'ın faktöriyeli hesaplanır ve döndürür. """
    if n == 0:
        return 1
    else:
        return n * factorial(n - 1)
```

